add('01-text-prep/bigrams','import re\nimport pandas as pd\nr=pd.read_csv("reviews_text.csv")\ndef tokenize(text):\n    return re.findall(r"[а-яё]+",text.lower())\nbad=r.rating<=3\ncb=Counter();cg=Counter()\nfor t,b in zip(r.text,bad):\n    w=tokenize(t)\n    (cb if b else cg).update(set(zip(w,w[1:])))\nd={k:cb[k]/bad.sum()-cg[k]/(~bad).sum() for k in cb}\ntop_bad=sorted(d,key=lambda k:-d[k])[:5]\ndiff_top=round(d[top_bad[0]],3)','top_bad пять кортежей по убыванию разности долей отзывов, не токенов; diff_top три знака')
