add('02-tfidf/keywords','def keywords(i,k=3):\n    a=T[i].toarray()[0]\n    ix=np.flatnonzero(a>0)\n    return names[ix[np.argsort(-a[ix])[:k]]].tolist()\nkw={i:keywords(i) for i in range(5)}\nshare_topic_word=sum(bool(set(keywords(i))&set(MARKERS[r.loc[i,"topic"]])) for i in range(200))/200','kw ключи0..4 по3слова;share_topic_word доля первых200отзывов с маркером основной темы')
