add('03b-labels/golden','gold_acc=wide.loc[gold.index].eq(gold,axis=0).mean().round(3).to_dict()\nworst=min(gold_acc,key=gold_acc.get)\nvote=wide.apply(majority,axis=1)\nvote_gold=round(float((vote.loc[gold.index]==gold).mean()),3)\nn_recheck=int((wide.drop(columns=worst).nunique(axis=1)>1).sum())','gold_acc .92/.78/.54,worstвика;vote_gold знаменатель50 включая нетбольшинства;перепроверка споров остальных')
add('03b-labels/kappa','def kappa(x,y):\n    x,y=list(x),list(y)\n    po=sum(a==b for a,b in zip(x,y))/len(x)\n    pe=sum(x.count(k)/len(x)*y.count(k)/len(y) for k in set(x)|set(y))\n    return (po-pe)/(1-pe)\nkappa_ab=round(kappa(wide["аня"],wide["борис"]),3)\nkappa_av=round(kappa(wide["аня"],wide["вика"]),3)\nprint(kappa_ab,cohen_kappa_score(wide["аня"],wide["борис"]))','kappa_ab.759;ручной расчёт совпадает sklearn;каппа не объясняет мотив людей')
add('03b-labels/topic-check','ab=wide["аня"]==wide["борис"]\nn_ab_agree=int(ab.sum())\nmatch_ab=round(float((topic[ab]==wide.loc[ab,"аня"]).mean()),3)\ndef majority(row):\n    c=row.value_counts()\n    return c.index[0] if c.iloc[0]>=2 else None\nmatch_vote=round(float((topic==wide[["аня","борис","вика"]].apply(majority,axis=1)).mean()),3)','match_ab знаменатель согласияАБ,match_vote450;topic иgold имеют общий источник,не независимая проверка')
add('03b-labels/train-labels','from sklearn.pipeline import make_pipeline\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nacc={}\nfor k in ["topic","аня","вика"]:\n    labels=r.loc[wide.index,"topic"] if k=="topic" else wide[k]\n    m=make_pipeline(TfidfVectorizer(),LogisticRegression(max_iter=1000)).fit(train_text,labels)\n    acc[k]=round(float((m.predict(rest.text)==rest.topic).mean()),3)','acc по1950общим текстам;topic около.76,вика около.35;это синтетические профили')
add('03b-labels/vote','wide=labels.pivot(index="review_id",columns="annotator",values="label")\ndef majority(row):\n    c=row.value_counts()\n    return c.index[0] if c.iloc[0]>=2 else None\nvote=wide.apply(majority,axis=1)\nn_no_majority=int(vote.isna().sum())\nshare_2of3=round(float((wide.nunique(axis=1)==2).mean()),3)','vote450строк,n_no_majority27,share_2of3 ровно двое согласны')

def write(lessons):
 for lesson in lessons:
  path=D/(lesson+'.input.jsonl')
  if path.exists():continue
  text=(P/(lesson+'.md')).read_text();rows=[]
  for id,(body,expected) in solutions.items():
   l,task=id.split('/')
   if l!=lesson:continue
   sec=text.split('## task: '+task+' |')[1].split('## task:')[0]
   starter=re.search(r'### Заготовка\s*```python\n(.*?)```',sec,re.S)
   pre=starter.group(1).replace('    ...','    pass') if starter else ''
   rows.append(dict(lesson=lesson,task=task,code=pre+'\n'+body,expect=expected,Q1='Самостоятельно получить '+expected,Q2='Публичная карточка «'+sec.splitlines()[0].strip()+'»: заполнить видимый редактор целым кодом по условию и теории урока.',Q3=expected))
  path.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
write(['01-text-prep','01b-lemmas','02-tfidf','03-classify','03b-labels'])
add('04-embeddings/char-search','def search(vec,T,q,k=5):\n    sim=(T@vec.transform([q]).T).toarray().ravel()\n    return r.iloc[np.argsort(-sim,kind="stable")[:k]].text.tolist()\ntop_words=search(w_vec,W,"курьер опоздал");top_chars=search(c_vec,C,"курьер опоздал")\nshare_late_words=sum("опоздал" in t.lower() for t in top_words)/5\nshare_late_chars=sum("опоздал" in t.lower() for t in top_chars)/5','по5текстов,stable сортировка;доли опоздал кратны.2;тематическая близость не гарантирует смысл')
add('04-embeddings/lsa','tfidf=TfidfVectorizer();X=tfidf.fit_transform(r.text)\nsvd=TruncatedSVD(n_components=50,random_state=0);Z=svd.fit_transform(X)\nZn=Z/np.linalg.norm(Z,axis=1,keepdims=True)\nexplained=round(float(svd.explained_variance_ratio_.sum()),2)\ni=r.index[r.review_id=="R-40002"][0]\nsim=Zn@Zn[i];sim[i]=-np.inf\nneighbours=r.iloc[np.argsort(-sim)[:3]].review_id.tolist()','Zn2400×50,explained≈.71,триID без самого запроса')
add('04-embeddings/skipgram','def skipgram_pairs(tokens,window=2):\n    return [(c,tokens[j]) for i,c in enumerate(tokens) for j in range(max(0,i-window),min(len(tokens),i+window+1)) if j!=i]\npairs=[p for t in r.text for p in skipgram_pairs(tokenize(t))]\nn_pairs=len(pairs)\ndef top(w):\n    return [c for c,n in Counter(b for a,b in pairs if a==w).most_common(3)]\ntop_courier=top("курьер");shared=set(top("дороговато"))&set(top("недорого"))','около63000 направленных пар;top_courier3;shared пересечение трёх соседей')
add('04-embeddings/zero-shot','tfidf=TfidfVectorizer();X=tfidf.fit_transform(r.text)\nsvd=TruncatedSVD(n_components=50,random_state=0);Z=svd.fit_transform(X)\nZn=Z/np.linalg.norm(Z,axis=1,keepdims=True)\nkeys=list(desc);V=svd.transform(tfidf.transform([desc[k] for k in keys]))\nV=V/np.linalg.norm(V,axis=1,keepdims=True)\nzs_pred=np.array(keys)[(Zn@V.T).argmax(axis=1)]\nzs_acc=round(float((zs_pred==r.topic).mean()),3)\nbase_acc=round(float(r.topic.value_counts(normalize=True).iloc[0]),3)','zs_pred2400тем;описания transform теми же tfidf/svd;две accuracy доли0..1')
add('04b-transformers/masked-pool','def mean_pool(H,mask):\n    return (H*mask[:,:,None]).sum(axis=1)/mask.sum(axis=1,keepdims=True)\npooled=mean_pool(H,attention_mask);naive=H.mean(axis=1)\ncos_short=round(float(pooled[2]@naive[2]/(np.linalg.norm(pooled[2])*np.linalg.norm(naive[2]))),3)\nsame=np.allclose(mean_pool(H_long,mask_long),pooled)','pooled3×5,sameTrue при4добавленныхPAD;cos_short ненулевой угол из-за мусора')
add('04c-llm/llm-check','import numpy as np\nTOPICS={"кофе","еда","обслуживание","доставка","цена","атмосфера"}\nans.index=true.index\nvalid=ans.isin(TOPICS);n_invalid=int((~valid).sum())\nok=valid&(ans==true)\nraw_accuracy=float(ok.mean());acc_llm=round(raw_accuracy,3)\nrecall_by_topic=ok.groupby(true).mean().round(3);worst=recall_by_topic.idxmin()\nse=np.sqrt(raw_accuracy*(1-raw_accuracy)/len(true))\nraw_low=raw_accuracy-2*se;low=round(float(raw_low),3);high=round(float(raw_accuracy+2*se),3)\nabove_reference=bool(raw_low>.79)','n_invalid включает None/внесписка;accuracy знаменатель200;above_reference сравнение неокруглённой границы одной доли с.79,не парный выигрыш')
add('04c-llm/llm-same','import numpy as np\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nrest=r[~r.review_id.isin(check.review_id)]\nm=make_pipeline(TfidfVectorizer(),LogisticRegression(max_iter=1000)).fit(rest.text,rest.topic)\nok_model=np.asarray(m.predict(check.text)==check.topic)\nl=np.asarray(ok_llm,dtype=bool)\nacc_model=round(float(ok_model.mean()),3)\nllm_only=int((l&~ok_model).sum());model_only=int((~l&ok_model).sum())\nd=l.astype(int)-ok_model.astype(int)\nbound=d.mean()-1.96*d.std(ddof=1)/np.sqrt(len(d))\npaired_lower=round(float(bound),3);within_margin=bool(bound>-.02)','исключение200поreview_id;остальные2200train;paired_lower парная разность,не интервалы каждойaccuracy;граница против-.02до округления')
add('04c-llm/parse-llm','TOPICS={"кофе","еда","обслуживание","доставка","цена","атмосфера"}\ndef parse(answer):\n    bad={"sentiment":None,"topic":None,"ok":False}\n    if not isinstance(answer,str) or not answer.strip():return bad\n    try:\n        d=json.loads(answer[answer.index("{"):answer.rindex("}")+1])\n    except (ValueError,TypeError):return bad\n    if not isinstance(d,dict) or d.get("sentiment") not in ("positive","negative") or d.get("topic") not in TOPICS:return bad\n    return {"sentiment":d["sentiment"],"topic":d["topic"],"ok":True}\nparsed=pd.DataFrame([parse(a) for a in raw])\nn_bad=int((~parsed.ok).sum())\nprint(parse(None),parse(""))','parsed8×3;None и пустота возвращают None/None/False без исключения')
