add('05-project/rare','import numpy as np\nclasses=sorted(r.topic.unique())\nm=new_model().fit(X_train,t_train);p=m.predict(X_test)\nf1_by_topic=dict(zip(classes,np.round(f1_score(t_test,p,labels=classes,average=None,zero_division=0),3)))\nmacro_f1=round(f1_score(t_test,p,labels=classes,average="macro",zero_division=0),3)\nrarest=t_test.value_counts().idxmin();worst=min(f1_by_topic,key=f1_by_topic.get)\ncount_ratio=round(float((p==rarest).sum()/(t_test==rarest).sum()),3)\nb=new_model("balanced").fit(X_train,t_train)\nf1_rare_balanced=round(float(f1_score(t_test,b.predict(X_test),labels=classes,average=None,zero_division=0)[classes.index(rarest)]),3)','полный список6тем,zero_division0;macro≈.794,rarestатмосфера,ratio≈.690,balanced≈.759')
add('05-project/weekly','n["week"]=n.date.dt.to_period("W-SUN").dt.start_time\nweekly=n.pivot_table(index="week",columns="shop_id",values="neg",aggfunc="mean")\na=n.assign(month=n.date.dt.month).pivot_table(index="shop_id",columns="month",values="neg",aggfunc="mean")\nfocus_shop=(a[10]-a[9]).idxmax()\njump_week=weekly[focus_shop].diff().idxmax()\nsept_max=round(float(weekly.loc[weekly.index<jump_week,focus_shop].max()),3)\nax=weekly[focus_shop].plot(kind="bar");ax.set(title="Доля сигналов "+focus_shop,xlabel="Понедельник недели",ylabel="Доля отзывов");plt.tight_layout();plt.show()\nprint(focus_shop,jump_week,n.groupby(["shop_id","week"]).size().loc[focus_shop].to_dict())','KZN-2 максимальный месячный прирост,jump5октября,sept_max.425;бар-график показывает те же недельные доли выбранной точки')
add('05-project/why','import pandas as pd\nimport numpy as np\na=n.assign(month=n.date.dt.month).pivot_table(index="shop_id",columns="month",values="neg",aggfunc="mean")\nfocus_shop=(a[10]-a[9]).idxmax()\nw=n.assign(week=n.date.dt.to_period("W-SUN").dt.start_time).pivot_table(index="week",columns="shop_id",values="neg",aggfunc="mean")\nchange_date=w[focus_shop].diff().idxmax()\nn=n.copy();n["period"]=np.where(n.date>=change_date,"после","до")\nassert n[n.shop_id==focus_shop].groupby("period").size().min()>=30\nbad=n[n.neg==1]\ndef tab(p):return pd.crosstab(p.topic,p.period,normalize="columns")\nkzn=tab(bad[bad.shop_id==focus_shop]);others=tab(bad[bad.shop_id!=focus_shop])\ncause=(kzn["после"]-kzn["до"]).idxmax()\nq=bad[(bad.shop_id==focus_shop)&(bad.period=="после")&(bad.topic==cause)].sort_values("p_neg",ascending=False).head(5)\nquotes=q.text.tolist();quote_ids=q.review_id.tolist()\nprint(q[["review_id","text"]].to_string(index=False))','выбор из своей таблицы KZN-2/5октября;доставка24.1→58.1%среди сигналов;5цитат с ID,внутри также кофе/приветствие/еда')
add('05-project/adjust','import numpy as np\nm=make_pipeline(TfidfVectorizer(ngram_range=(1,2)),LogisticRegression(max_iter=1000)).fit(X_train,y_train)\ntn,fp,fn,tp=confusion_matrix(y_test,m.predict(X_test),labels=[0,1]).ravel()\ntpr=tp/(tp+fn);fpr=fp/(fp+tn)\nn=n.copy();n["period"]=np.where(n.date>=pd.Timestamp("2026-10-05"),"после","до")\nf=n[n.shop_id=="KZN-2"]\nadj={k:round(float((p-fpr)/(tpr-fpr)),3) for k,p in f.groupby("period").neg.mean().items()}\ng=n.merge(pd.read_csv("reviews_new_gold.csv"),on="review_id",validate="one_to_one",suffixes=("","_gold"))\nrows=[]\nfor period,p in g[g.shop_id=="KZN-2"].groupby("period"):\n    tn1,fp1,fn1,tp1=confusion_matrix(p.complaint,p.neg,labels=[0,1]).ravel()\n    a=tp1/(tp1+fn1);b=fp1/(fp1+tn1);obs=p.neg.mean()\n    rows.append(dict(period=period,n=len(p),complaints=int(p.complaint.sum()),tpr=a,fpr=b,observed=obs,manual=p.complaint.mean(),adjusted=(obs-b)/(a-b)))\naudit=pd.DataFrame(rows).set_index("period")','tpr.917/fpr.034;adj.378/.637;auditдо440/161,после372/222;источникsynthetic;приTPR<FPRзнакобратный,=неидентифицируемо')
